using UnityEngine;

namespace Stealth.Audio
{
    /// <summary>
    /// Every sound the game plays (Data/SoundBank.asset, filled by the asset builder from Art/Audio — cut from recordings by
    /// Tools/Audio/recorded.py, the rest generated by Tools/Audio/generate_sounds.py). Swap a clip here to change a sound everywhere.
    /// </summary>
    [CreateAssetMenu(menuName = "Stealth/Sound Bank")]
    public class SoundBank : ScriptableObject
    {
        [Header("Player")]
        [Tooltip("A player's steps by what they land on (StepSurfaces): four of each.")]
        public AudioClip[] StepConcrete, StepTile, StepWood, StepSoft, StepCarpet, StepMetal, StepWet;
        public AudioClip Jump, Land, Hurt, Downed, Revive;

        [Header("Items")]
        public AudioClip Pickup, Drop, Sell, Stash;

        [Header("Interface")]
        public AudioClip Click, Hover, BackpackOpen, Banner, RunFailed, LevelDone;
        [Tooltip("A teammate's ping / a robot marked for the team.")]
        public AudioClip Ping, Mark;

        [Header("Robots")]
        public AudioClip Suspicious, Alert, Lost, Hacked, Radio, TurretShot, RobotStep, RobotMotor, DroneRotor;
        [Tooltip("Seismic robot stomping the floor (its wave runs out).")]
        public AudioClip SeismicThump;
        [Tooltip("A camera that is noticing someone beeps, faster and faster.")]
        public AudioClip CameraBeep;
        [Tooltip("A hound's paw / a spider's foot (the guard's foot is RobotStep).")]
        public AudioClip StepLight, SpiderStep;
        [Tooltip("Motor loops of the other robots: joints of legged ones, tracks, the sweeper's brush, the hunter's turbine.")]
        public AudioClip MotorServo, MotorTracks, MotorBrush, MotorTurbine;
        [Tooltip("A guard's loops (GuardSounds): resting on its dock, walking its rounds, chasing.")]
        public AudioClip GuardCharge, GuardPatrol, GuardChase;

        [Header("Items and places")]
        [Tooltip("The lure speaker's music (loop).")]
        public AudioClip SpeakerMusic;
        public AudioClip FuelGulp, Heal, Craft, StunBlast, CrateSearch, Unlock, GateOpen;

        [Header("Car")]
        [Tooltip("Engine loop at idle: pitched up with the revs.")]
        public AudioClip CarEngine;
        public AudioClip CarStart, CarStop, CarHorn, CarBump;

        [Header("Robot voice (Tools/Audio/generate_voices.py)")]
        [Tooltip("«Обнаружен нарушитель» — a robot has noticed someone; the chase starts after its warning time.")]
        public AudioClip VoiceSpotted;
        [Tooltip("«Веду преследование» — the chase begins.")]
        public AudioClip VoiceChase;
        [Tooltip("«Нарушитель потерян» — lost the target, goes to check the last known spot.")]
        public AudioClip VoiceLost;
        [Tooltip("«Нарушитель устранён» — it knocked its target down and goes back to work.")]
        public AudioClip VoiceEliminated;

        [Header("People")]
        [Tooltip("A player breathing hard in the laughing gas (before the laughing starts).")]
        public AudioClip GasBreath;
        [Tooltip("A player coughing in the gas, ever harder: a couple of coughs, three hard ones, a fit.")]
        public AudioClip[] GasCough = new AudioClip[0];
        [Tooltip("The hostage calling to a player who sees it (Tools/Audio/generate_voices.py).")]
        public AudioClip[] HostageVoice = new AudioClip[0];

        [Header("Environment")]
        public AudioClip LaserHum, DoorSlide, Alarm, OfficeHum, GasWind;
        [Tooltip("A hinged door: the handle's click and a short creak as it opens; the latch's thud as it shuts.")]
        public AudioClip DoorOpen, DoorShut;
        [Tooltip("A steel door: the bolt and the sheet; the heavy thud.")]
        public AudioClip DoorHeavyOpen, DoorHeavyShut;
        [Tooltip("Furniture that opens: a wooden drawer and cupboard, a steel one.")]
        public AudioClip DrawerOpen, DrawerClose, SteelDrawerOpen, SteelDrawerClose, CupboardOpen, CupboardClose, SteelCupboardOpen, SteelCupboardClose;
        [Tooltip("A light switch; the shaft's iron lid; a vent's grille coming off.")]
        public AudioClip SwitchOn, SwitchOff, HatchOpen, GrilleOff;
        [Tooltip("Ticks while a player works at something with E held: hacking (a robot, a terminal), picking a lock, unscrewing a grille.")]
        public AudioClip[] WorkHack = new AudioClip[0], WorkPick = new AudioClip[0], WorkScrew = new AudioClip[0];
        [Tooltip("The robots' electronic lock: working at it (a relay, a probe on its board) and its bolt drawn once it is hacked.")]
        public AudioClip[] WorkUnit = new AudioClip[0];
        public AudioClip UnlockUnit;
        [Tooltip("A safe's dial going over a mark; a wrong try's clank; a number found; a key of a terminal or a lock panel.")]
        public AudioClip SafeTick, Clank, Latch, TerminalKey;
        [Tooltip("A bandage wound on; coffee drunk.")]
        public AudioClip Bandage, Drink;
        [Tooltip("The car's shredder biting into a thing (one per thing, CarShredder).")]
        public AudioClip Grind;
        [Tooltip("A restroom's hand dryer running (4 s, loud: robots come to check).")]
        public AudioClip HandDryer;

        [Header("Music")]
        public AudioClip MenuMusic, ExploreMusic, ChaseMusic;

        /// <summary>The steps on a surface.</summary>
        public AudioClip[] Steps(StepSurface surface) => surface switch
        {
            StepSurface.Tile => StepTile,
            StepSurface.Wood => StepWood,
            StepSurface.Soft => StepSoft,
            StepSurface.Carpet => StepCarpet,
            StepSurface.Metal => StepMetal,
            StepSurface.Wet => StepWet,
            _ => StepConcrete,
        };

        /// <summary>One of several takes of a sound (null: none).</summary>
        public static AudioClip Any(AudioClip[] clips) =>
            clips == null || clips.Length == 0 ? null : clips[Stealth.Level.LevelRandom.Shared(Stealth.Level.RandomChannel.Audio).Next(clips.Length)];

        /// <summary>The clip of something the server tells everyone about.</summary>
        public AudioClip Of(GameSound sound) => sound switch
        {
            GameSound.Craft => Craft,
            GameSound.Heal => Heal,
            GameSound.Bandage => Bandage,
            GameSound.Drink => Drink,
            GameSound.Stun => StunBlast,
            _ => null,
        };
    }

    /// <summary>A sound the server tells every peer to play (<see cref="Stealth.Game.IGameLink.BroadcastSound"/>): what is heard of something only it decides.</summary>
    public enum GameSound : byte { Craft, Heal, Bandage, Drink, Stun }
}
